    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            region = []
            edges = set()
            while q:
                x, y = q.popleft()
                region.append((x, y))
                if x == 0: edges.add('top')
                if x == h - 1: edges.add('bottom')
                if y == 0: edges.add('left')
                if y == w - 1: edges.add('right')
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == bg and (a, b) not in seen:
                        seen.add((a, b))
                        q.append((a, b))
            # Fill enclosed pockets; a grid edge may serve as one side, but
            # regions opening onto two or more outer edges are exterior space.
            if len(edges) <= 1:
                for x, y in region:
                    out[x][y] = 4
    return out
